import type { Metadata } from "next";
import { getSettings } from "@/lib/catalog";

export const metadata: Metadata = { title: "Photo credits" };

type Credit = { title: string; creator: string; license: string; source: string };

async function Credits() {
  const raw = (await getSettings()).photoCredits;
  let credits: Credit[] = [];
  try {
    credits = raw ? JSON.parse(raw) : [];
  } catch {}
  if (!credits.length) return <p className="text-sm text-muted">All photos on this site are our own.</p>;
  return (
    <ul className="divide-y divide-line rounded-lg border border-line bg-white text-sm">
      {credits.map((c) => (
        <li key={c.source + c.title} className="flex flex-wrap items-baseline justify-between gap-2 px-4 py-3">
          <span>“{c.title}” by <span className="font-medium">{c.creator}</span></span>
          <span className="text-muted">
            {c.license === "CC0" ? "CC0 (public domain)" : <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noopener noreferrer" className="hover:underline">{c.license}</a>} ·{" "}
            <a href={c.source} target="_blank" rel="noopener noreferrer" className="text-maroon hover:underline">source</a>
          </span>
        </li>
      ))}
    </ul>
  );
}

export default function CreditsPage() {
  return (
    <div className="container-x max-w-3xl py-10">
      <h1 className="mb-2 font-display text-3xl font-semibold">Photo credits</h1>
      <p className="mb-6 text-sm text-muted">Some lifestyle photos are used under Creative Commons licences. Thank you to these photographers.</p>
      <Credits />
    </div>
  );
}
